export const HEALTH_EVENTS = {
    ADD_WORKOUT: 'health:add-workout',
    ADD_FOOD: 'health:add-food',
    EDIT_WORKOUT: 'health:edit-workout',
    /**
     * Story 323: the owner confirmed they attended a Google Calendar class, so the projection
     * should become a stored row. Delegated up rather than written in the card because the day
     * detail is a plain element with no status surface — the screen owns loading and errors, and
     * "Fail Loudly" needs a place to fail.
     */
    ADOPT_CALENDAR_ACTIVITY: 'health:adopt-calendar-activity',
    // Story 342: "Change" on a binding's confirmation — re-ask the question for a code already
    // bound. Re-binding replaces (340's newest-intent-wins), so correcting a wrong pick needs no unbind.
    MAP_BARCODE_CHANGE: 'health:map-barcode-change',
    // Story 344/372: the "also remember this code" box. Its host owns the one consent flag.
    BIND_CONSENT_CHANGE: 'health:bind-consent-change',
    /**
     * Story 403: `<photo-controls>` uploaded a photo, or Remove was pressed. The element never
     * writes a row: its host saves or holds the path, answering through `respondWith` so a failed
     * save shows in the element's error line.
     */
    PHOTO_PICKED: 'health:photo-picked',
    PHOTO_REMOVED: 'health:photo-removed',
    /** Story 403: a queued photo shipped, and the drain already put it on its row. */
    PHOTO_LANDED: 'health:photo-landed',
    /** Story 403: an upload started or settled — a host holding the photo for a save waits on it. */
    PHOTO_UPLOADING: 'health:photo-uploading',
    DAY_MEAL_SECTION_ADD: 'health:day-meal-section-add',
    // Story 258: the quick-log bar's `›` — the screen opens its more-actions menu.
    QUICK_LOG_MORE: 'health:quick-log-more',
    /** Story 307: the day's Activity tab asks its screen to open the sync dialog. */
    HC_SYNC_REQUEST: 'health:hc-sync-request',
    /**
     * Story 307: an `<hc-sync-panel>` sync changed stored activity data —
     * created, upgraded or backfilled rows, or step days; since 376 also when a
     * later leg of that sync failed. Hosts that render activities re-fetch; the
     * Status screen ignores it.
     */
    HC_SYNC_APPLIED: 'health:hc-sync-applied',
    // Workout-session events (story 143)
    /**
     * A set became complete. Story 288 moved the trigger off the ✓ button
     * (which was removed — it was never used) onto the edit itself: a row
     * emits this when an edit leaves every field the exercise tracks filled
     * and at least one of them was empty before. The "was empty before" half
     * is what stops a re-render from re-firing the card's rest timer.
     */
    STRENGTH_SET_COMPLETE: 'health:strength-set-complete',
    STRENGTH_SET_EDIT: 'health:strength-set-edit',
    STRENGTH_SET_DELETE: 'health:strength-set-delete',
    STRENGTH_SET_ADD_REQUEST: 'health:strength-set-add-request',
    EXERCISE_REMOVE_FROM_SESSION: 'health:exercise-remove-from-session',
    /** Story 288: the card's both-arms ↔ one-arm toggle. Persists to the library entry. */
    EXERCISE_LATERALITY_TOGGLE: 'health:exercise-laterality-toggle',
    REST_TIMER_FINISH: 'health:rest-timer-finish',
    // Story 420 — the shared nutrition elements. They never write: editors emit, screens save.
    AMOUNT_CHANGE: 'health:amount-change',
    LINE_OPEN: 'health:line-open',
    LINE_AMOUNT_CHANGE: 'health:line-amount-change',
    LINE_REMOVE: 'health:line-remove',
    LINES_CHANGE: 'health:lines-change',
    LINE_ADD_REQUEST: 'health:line-add-request',
    LOG_MENU: 'health:log-menu',
    SAVE_LOGS_AS_MEAL: 'health:save-logs-as-meal',
    FOOD_CARD_SELECT: 'health:food-card-select',
    FOOD_PICK: 'health:food-pick',
    FOOD_PICK_ACTION: 'health:food-pick-action',
    LINE_EDITOR_SAVE: 'health:line-editor-save',
    LINE_EDITOR_REMOVE: 'health:line-editor-remove',
    // Story 422 — a log on the day, and the editor of a list of lines.
    LOG_ACTION: 'health:log-action',
    LINE_SET_SAVE: 'health:line-set-save',
    LINE_SET_DELETE: 'health:line-set-delete',
    LINE_PICKED: 'health:line-picked',
    // Story 423 — `<food-editor>`; the screen writes.
    FOOD_EDITOR_SAVE: 'health:food-editor-save',
    FOOD_EDITOR_ARCHIVE: 'health:food-editor-archive',
    FOOD_EDITOR_DELETE: 'health:food-editor-delete',
    FOOD_EDITOR_BARCODE_ADD: 'health:food-editor-barcode-add',
    FOOD_EDITOR_BARCODE_REMOVE: 'health:food-editor-barcode-remove',
} as const;

export interface HealthEventMap {
    [HEALTH_EVENTS.ADD_WORKOUT]: { date: string };
    [HEALTH_EVENTS.ADD_FOOD]: { date: string; meal: string };
    [HEALTH_EVENTS.EDIT_WORKOUT]: { activity: Activity };
    // Story 371: the save events carry `respondWith` — the screen answers with
    // the promise of its work, and the button stays disabled until it settles.
    [HEALTH_EVENTS.ADOPT_CALENDAR_ACTIVITY]: { activity: Activity } & Settles;
    [HEALTH_EVENTS.MAP_BARCODE_CHANGE]: { barcode: string };
    [HEALTH_EVENTS.BIND_CONSENT_CHANGE]: { consent: boolean };
    [HEALTH_EVENTS.PHOTO_PICKED]: { image_path: string } & Settles;
    [HEALTH_EVENTS.PHOTO_REMOVED]: Settles;
    [HEALTH_EVENTS.PHOTO_LANDED]: { image_path: string };
    [HEALTH_EVENTS.PHOTO_UPLOADING]: { uploading: boolean };
    [HEALTH_EVENTS.DAY_MEAL_SECTION_ADD]: { meal: string };
    [HEALTH_EVENTS.QUICK_LOG_MORE]: undefined;
    [HEALTH_EVENTS.HC_SYNC_REQUEST]: undefined;
    [HEALTH_EVENTS.HC_SYNC_APPLIED]: { summary: HcSyncSummary };
    [HEALTH_EVENTS.STRENGTH_SET_COMPLETE]: { set_id: string; exercise_id: string; rest_s: number | null };
    [HEALTH_EVENTS.STRENGTH_SET_EDIT]: { set_id: string; updates: StrengthSetUpdate };
    [HEALTH_EVENTS.STRENGTH_SET_DELETE]: { set_id: string };
    [HEALTH_EVENTS.STRENGTH_SET_ADD_REQUEST]: { exercise_id: string };
    [HEALTH_EVENTS.EXERCISE_REMOVE_FROM_SESSION]: { exercise_id: string };
    [HEALTH_EVENTS.EXERCISE_LATERALITY_TOGGLE]: { exercise_id: string; is_unilateral: number };
    [HEALTH_EVENTS.REST_TIMER_FINISH]: undefined;
    /** `<amount-input>`: a valid amount, after a step, a preset or typing. */
    [HEALTH_EVENTS.AMOUNT_CHANGE]: { value: number };
    /** A line was tapped; `log_id` when it sits in a `<log-block>`. */
    [HEALTH_EVENTS.LINE_OPEN]: { key: string; log_id?: string };
    [HEALTH_EVENTS.LINE_AMOUNT_CHANGE]: { key: string; amount: number };
    [HEALTH_EVENTS.LINE_REMOVE]: { key: string };
    /** `<line-list>`: the whole list after an edit — amounts, removals or a scale. */
    [HEALTH_EVENTS.LINES_CHANGE]: { lines: LineView[] };
    [HEALTH_EVENTS.LINE_ADD_REQUEST]: undefined;
    [HEALTH_EVENTS.LOG_MENU]: { log_id: string };
    /** Story 430: logs picked on the day, in day order, to become one meal. */
    [HEALTH_EVENTS.SAVE_LOGS_AS_MEAL]: { log_ids: string[] };
    [HEALTH_EVENTS.FOOD_CARD_SELECT]: { entry: FoodCardEntry };
    /**
     * `<food-picker>`: what was picked — a library food, a saved meal, or an Open Food Facts product.
     * Story 432: `scanned` — the picker's own scan found this: the code, and `pending` when it was
     * found through a sibling or item code, so the exact one could be taught (369); `bind` — a
     * dead-end code the user agreed to teach this pick (340, 344). The host binds either.
     */
    [HEALTH_EVENTS.FOOD_PICK]: { entry: FoodCardEntry; scanned?: { barcode: string; pending: string | null }; bind?: string | null };
    /** `<food-picker>`: read a label, or estimate — `query` is what was typed. Scan is the picker's own. */
    [HEALTH_EVENTS.FOOD_PICK_ACTION]: { action: FoodPickAction; query: string };
    /** `<line-editor>`: Done — the amount, and an override when one is on (story 371: the button waits on the write). */
    [HEALTH_EVENTS.LINE_EDITOR_SAVE]: { amount: number; override: Partial<LineNutrition> | null } & Settles;
    [HEALTH_EVENTS.LINE_EDITOR_REMOVE]: Settles;
    /** `<log-menu>`: what to do with a log on the day — the day screen does it. */
    [HEALTH_EVENTS.LOG_ACTION]: { log_id: string; action: LogMenuAction };
    /** `<line-set-editor>`: Save — the whole set as edited; `time` is HH:MM or '' (unstamped). */
    [HEALTH_EVENTS.LINE_SET_SAVE]: LineSetValue & Settles;
    [HEALTH_EVENTS.LINE_SET_DELETE]: Settles;
    /**
     * `<line-add-dialog>`: a food picked to join a list, as a line at its default amount.
     * `bind` (story 432): a dead-end scanned code the user agreed to teach this food; the screen binds it.
     */
    [HEALTH_EVENTS.LINE_PICKED]: { line: LineView; bind?: string | null };
    /** `<food-editor>`: Save — the food as edited (a `NewFoodItem`'s fields, photo included). */
    [HEALTH_EVENTS.FOOD_EDITOR_SAVE]: { food: NewFoodItem } & Settles;
    [HEALTH_EVENTS.FOOD_EDITOR_ARCHIVE]: { archived: boolean } & Settles;
    /** Delete, after the editor's confirm said yes. */
    [HEALTH_EVENTS.FOOD_EDITOR_DELETE]: Settles;
    [HEALTH_EVENTS.FOOD_EDITOR_BARCODE_ADD]: { barcode: string } & Settles;
    [HEALTH_EVENTS.FOOD_EDITOR_BARCODE_REMOVE]: { barcode: string } & Settles;
}

export type LogMenuAction =
    | { kind: 'edit' }
    | { kind: 'scale'; factor: number }
    | { kind: 'move'; date: string; meal_type: MealType }
    | { kind: 'save-as-meal'; name: string }
    | { kind: 'delete' };

export interface LineSetValue {
    name: string;
    date: string;
    meal_type: MealType;
    time: string;
    lines: LineView[];
    /** Log mode, when the log came from a meal: also put these lines on the meal (418 #8); draft mode: also save them as one (423). */
    also_update_meal: boolean;
    /** Meal mode: the notes (null when empty) and the cover as picked. */
    notes: string | null;
    image_path: string | null;
}

/** One `<food-card>`: a library food, a saved meal (with its kcal when known), or an OFF product. */
export type FoodCardEntry =
    | { kind: 'food'; item: FoodItem }
    | { kind: 'meal'; meal: Meal; calories?: number | null; ingredient_count?: number }
    | { kind: 'off'; product: OFFProduct };

export const FOOD_PICK_ACTIONS = ['scan', 'label', 'estimate'] as const;
export type FoodPickAction = typeof FOOD_PICK_ACTIONS[number];

export type HealthEvent<K extends keyof HealthEventMap> = CustomEvent<HealthEventMap[K]>;

export function createHealthEvent<K extends keyof HealthEventMap>(
    type: K,
    detail: HealthEventMap[K]
): HealthEvent<K> {
    return new CustomEvent(type, {
        bubbles: true,
        composed: true,
        detail,
    }) as HealthEvent<K>;
}

